349: func matchAnchor(anchor, target, workspaceRoot string) bool {
350: 	cleanA := filepath.Clean(anchor)
351: 	cleanT := filepath.Clean(target)
352: 	if cleanA == cleanT {
353: 		return true
354: 	}
355: 	if filepath.Join(workspaceRoot, cleanA) == filepath.Join(workspaceRoot, cleanT) {
356: 		return true
357: 	}
358: 	if strings.HasSuffix(cleanA, "/"+cleanT) || strings.HasSuffix(cleanT, "/"+cleanA) {
359: 		return true
360: 	}
361: 	if !strings.Contains(cleanT, string(filepath.Separator)) && filepath.Base(cleanA) == cleanT {
362: 		return true
363: 	}
364: 	if !strings.Contains(cleanA, string(filepath.Separator)) && filepath.Base(cleanT) == cleanA {
365: 		return true
366: 	}
367: 	return false
368: }
