370: func hasEntriesInContext(ctx context.Context, idx *index.Index, ledger *delivery.Ledger, workspaceRoot, targetFile string) bool {
371: 	for _, inj := range ledger.Injections {
372: 		ent, err := idx.GetEntry(ctx, inj.EntryID)
373: 		if err == nil && ent != nil {
374: 			for _, a := range ent.Anchors {
375: 				if matchAnchor(a, targetFile, workspaceRoot) {
376: 					return true
377: 				}
378: 			}
379: 		}
380: 	}
381: 
382: 	for seenAnchor := range ledger.SeenAnchors {
383: 		if matchAnchor(seenAnchor, targetFile, workspaceRoot) {
384: 			ids, err := idx.LookupByAnchor(ctx, seenAnchor)
385: 			if err == nil && len(ids) > 0 {
386: 				return true
387: 			}
388: 		}
389: 	}
390: 
391: 	return false
392: }
