35: 
36: 	var nextStepIdx = 999999999
37: 	for i := checkpointIdx + 1; i < len(steps); i++ {
38: 		if !steps[i].IsCheckpoint && !steps[i].IsGap {
39: 			nextStepIdx = steps[i].StepIndex
